SELECT city, CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(rating) AS max_rating FROM suppliers WHERE country <> 'TH' GROUP BY city, CASE WHEN rating >= 4.0 THEN 'high' WHEN rating >= 2.5 THEN 'mid' ELSE 'low' END HAVING MAX(rating) >= 2.8 ORDER BY city DESC, max_rating
